"""Complete Picayune and Creole sauces, celery, chicken, crab and salmon dishes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

merges=[];updatedids=[]
def merge(n,r,reason):
 s=src(n);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason=reason)
 if s['id'] not in r['sourceAliases']:r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source']
 records.pop(s['id'],None);merges.append(s)

def picitems():return [yolks(1),oil(240),lemon(15),salt(.25),pepper(.125)]
PICSTEPS=['Whisk {{yolks}} in a clean bowl set on a damp towel. Measure {{oil|0.0625}} into a small cup and whisk it in a few drops at a time until evenly blended.','Measure {{lemon}} into a small cup and {{oil|0.9375}} into a jug. Gradually whisk in this remaining oil, alternating with small additions of the measured lemon juice as the sauce thickens, and finish with the last of the measured oil. Stop pouring if oil pools and whisk until it blends in.','Whisk in {{salt}} and {{pepper}} only after the oil and lemon are incorporated. The finished sauce should be smooth and creamy.',COLD]
r=add(78,'Picayune Lemon Mayonnaise',18,15,'A simple yolk mayonnaise alternates olive oil and lemon juice, then finishes with salt and pepper.',picitems(),PICSTEPS,
 'Both imported entries repeat the same Picayune Mayonnaise Dressing paragraph. Two gills of oil are represented by a modern working 240 ml, using the book’s US context; half a lemon becomes a working 15 ml. Seasonings and eighteen small tablespoon-size servings are supplied. The method specifically uses lemon although the heading also lists vinegar; a complete vinegar alternative is supplied as an explicitly chosen variation. The original larger-salad instruction triples the yolks and all other ingredients; use the app’s serving control to triple the recipe. The cold stirring thickens an emulsion and does not cook the egg.');eggsource(r)
vi=copy.deepcopy(r['ingredients'])
for i in vi:
 if i['key']=='lemon':i.update(key='vinegar',name='white wine vinegar',substitution='Use the lemon base recipe if preferred.')
variant(r,'vinegar','With white wine vinegar',vi,[s.replace('{{lemon}}','{{vinegar}}').replace('lemon juice','vinegar').replace('lemon are','vinegar are') for s in r['steps']])
merge(76,r,'Same original Picayune Mayonnaise Dressing paragraph, including one yolk, about two gills oil, half a lemon and an oil finish; larger-batch guidance retained in canonical78.')

r=add(74,'Creole Cookery Book Mustard Mayonnaise',18,15,'Prepared mustard seasons a yolk-and-olive-oil mayonnaise, with vinegar stirred in at the end.',[yolks(1),I('mustard',1,'tsp','prepared smooth mustard','Use the same amount of prepared Dijon mustard.'),salt(1),oil(240),vinegar(15)],
 ['Mix {{mustard}} and {{salt}} in a clean bowl, then whisk in {{yolks}} until smooth. Measure {{oil}} into a jug and whisk it in a few drops at a time at first, then in a thin stream once the sauce thickens. Stop adding oil if it pools and whisk until it blends in.','Gradually whisk in {{vinegar}} until smooth. Serve as a condiment with chilled cooked foods.',COLD],
 'The source specifies one yolk, one teaspoon each prepared mustard and salt, and one tablespoon vinegar, but no oil quantity. A modern 240 ml oil batch and eighteen small condiment servings are supplied. The full teaspoon salt is retained and makes a strongly seasoned sauce; the substitution allows reduction. The red-pepper variation preserves the original suggestion for shrimp or oysters. Pasteurized yolk replaces the untreated raw yolk.');eggsource(r)
variant(r,'red-pepper','With red pepper',copy.deepcopy(r['ingredients'])+[cayenne()],r['steps'][:-1]+['Whisk in {{cayenne}} and serve with fully cooked chilled seafood.']+[COLD])

def mayo(a):return I('mayo',a,'ml','plain prepared mayonnaise, kept refrigerated','Use the complete homemade-mayonnaise variation below; its measured portion replaces this amount.')
def homemade(r):
 a=next(i['amount'] for i in r['ingredients'] if i['key']=='mayo')
 vi=[I('mayoreserve',a,'ml','mayonnaise portion reserved from the homemade batch below; not an additional purchase','Use the prepared-mayonnaise base recipe for a quicker version.') if i['key']=='mayo' else copy.deepcopy(i) for i in r['ingredients']]
 pi=copy.deepcopy(picitems())
 for i in pi:i['key']='hm'+i['key'];i['name']='for homemade mayonnaise: '+i['name']
 hs=PICSTEPS[:-1]
 for k in ['yolks','oil','lemon','salt','pepper']:hs=[s.replace('{{'+k,'{{hm'+k) for s in hs]
 vs=[s.replace('{{mayo}}','{{mayoreserve}}') for s in r['steps']]
 variant(r,'homemade-mayonnaise','With homemade Picayune mayonnaise',vi+pi,hs+['Cover and refrigerate the homemade sauce while preparing the rest of the dish.']+vs+['The measured mayonnaise portion comes from this homemade batch, which makes about 270 ml. Refrigerate extra sauce separately at 4°C (40°F) or colder and use within 3 days; do not add all the extra sauce to the dish.'])
 r['notes']+=' Prepared mayonnaise is a modern shortcut. The complete homemade variation supplies the Picayune one-yolk formula, reserves the specified portion and accounts for surplus sauce. Allow about 15 additional minutes for making it.';eggsource(r)
def celerytips(a=10):return I('celerytips',a,'g','tender celery leaves and inner tips, washed and dried','Use the same weight of flat-leaf parsley.')
def beet(a=150):return I('beet',a,'g','raw beetroot, scrubbed','Use the same weight of plain commercially cooked beetroot; omit its boiling step.')
def beetsteps():return ['Cover {{beet}} with {{beetwater}} in a saucepan, topping up with drinking water only if needed to cover. Simmer for about 30–45 minutes until a knife enters easily. Drain, cool enough to handle, peel and slice thinly. Refrigerate promptly in a covered shallow container until cold.']

r=add(71,'Picayune Celery Salad with Mayonnaise',4,10,'Crisp white celery is finely sliced, dressed with mayonnaise and finished with tender celery tips.',[I('celery',200,'g','tender pale celery stalks, washed and dried','Use the same weight of tender inner celery stalks.'),mayo(60),celerytips()],
 ['Remove any tough strings from {{celery}} and cut crosswise into thin slices about 6 mm wide. Mix with {{mayo}} until lightly coated.','Transfer to a serving bowl and garnish with {{celerytips}}. Serve immediately while crisp.','Keep covered at 4°C (40°F) or colder and use within 1 day; the celery gradually releases moisture.'],
 'The original one pint of chopped celery is represented by a working 200 g of loosely packed sliced celery, not a universal cup-to-weight conversion. Mayonnaise amount, garnish weight and four side servings are supplied. The preceding recipe specifies quarter-inch pieces. The source explicitly prefers mustard dressing as an alternative; both its plain and optional yolk versions are retained.');r['category']='Salads';homemade(r)
mi=[copy.deepcopy(r['ingredients'][0]),celerytips(),I('mustard',1,'tsp','prepared smooth mustard','Use the same amount of Dijon mustard.'),oil(30),vinegar(15),salt(.125),pepper(.0625)]
ms=['Mix {{mustard}} in a small bowl with {{oil}}, adding the oil drop by drop at first while whisking. Gradually whisk in {{vinegar}}, {{salt}} and {{pepper}} until blended. Whisk again if it separates.','Remove tough strings from {{celery}}, slice crosswise about 6 mm thick and toss with the dressing. Garnish with {{celerytips}} and serve immediately.','Keep covered and refrigerated at 4°C (40°F) or colder and use within 1 day.']
variant(r,'mustard-dressing','With mustard dressing',mi,ms)
variant(r,'mustard-yolk','With mustard and yolk dressing',copy.deepcopy(mi)+[yolks(1)],[ms[0].replace('Mix {{mustard}}','Whisk {{yolks}} and {{mustard}}')]+ms[1:])

r=add(72,'Picayune Chicken Salad with Mayonnaise',6,120,'Poached chicken and crisp celery are topped with mayonnaise and arranged with eggs, asparagus, beets, olives and lemon.',[
 I('chicken',700,'g','raw boneless skinless chicken breast','Use the same weight of boneless skinless chicken thigh, cooking to the same safe temperature.'),I('stock',1500,'ml','unsalted prepared chicken stock for poaching','Use the same volume of unsalted vegetable stock.'),I('cookedchicken',500,'g','cooked chicken reserved from poaching below; not an additional purchase','Use the same weight of plain commercially cooked chicken for the source leftover-chicken option, omitting the raw-chicken poaching step.'),I('celery',170,'g','tender celery stalks, washed and dried','Use the same weight of tender inner celery stalks.'),I('onion',1,'','small onion, peeled and finely chopped','Use one small shallot per onion for a milder flavor.'),salt(.25),pepper(.125),mayo(120),eggs(3),water(1000),beet(),water(1000,'beetwater'),I('asparagus',120,'g','asparagus tips, trimmed','Use the same weight of trimmed green beans; cook until tender.'),water(750,'asparaguswater'),I('olives',40,'g','drained pitted green olives','Use the same weight of pitted black olives.'),I('garnishlemon',1,'','small lemon, washed and sliced','Use one small lime per lemon.'),celerytips()],
 ['Bring {{stock}} to a gentle simmer, add {{chicken}} and poach for about 15–20 minutes until the thickest part reaches 74°C (165°F). Lift out and measure {{cookedchicken}} from the cooked meat. Cut into pieces about 2 cm across, spread in a shallow container and refrigerate promptly until cold, about 45–60 minutes. Refrigerate extra cooked meat and broth separately for use within 2 days.']+beetsteps()+boil()+[
 'Slice the firm hard-boiled eggs and refrigerate. Bring {{asparaguswater}} to a boil, add {{asparagus}} and simmer for about 2–4 minutes until tender. Drain, refresh under cold drinking water, drain thoroughly and refrigerate until assembly.',
 'Finely slice {{celery}} and mix with the cold measured chicken, {{onion}}, {{salt}} and {{pepper}}. Arrange on a platter and spread {{mayo}} over the top. Garnish with the cold beet slices, asparagus, sliced eggs, {{olives}}, {{garnishlemon}} and {{celerytips}}. Serve cold.',END],
 'This follows the original chicken chapter recipe, not a different layered salad elsewhere in the book. A modern 500 g cooked chicken portion and 170 g celery represent the source’s approximately one-third celery relative to chicken. The original onion and three hard-boiled eggs are retained; although the source method omits the listed eggs, they are used as garnish here. All other amounts, poaching, vegetable cooking, chilling and six portions are supplied. Preparing eggs and vegetables while the chicken chills keeps the estimated total near two hours.');finish(r);homemade(r)

r=add(73,'Picayune Crab Salad with Mayonnaise',4,160,'Crab cooked in an aromatic herb-and-spice broth is served cold on lettuce with mayonnaise, eggs, beets and celery tips.',[
 I('crabs',12,'','small whole blue crabs, about 200 g each, freshly dispatched and cleaned by the fishmonger, kept chilled','Use enough commercially cooked picked crab to supply the measured meat portion below, and omit the crab boil.'),water(5000,'crabwater'),I('boilcelery',200,'g','celery stalks and tops, cleaned and chopped','Use the same weight of cleaned celery stalks.'),I('allspice',24,'','whole allspice berries','Use half a teaspoon ground allspice for the entire base batch; scale proportionally.'),I('thyme',4,'','small fresh thyme sprigs','Use 1 teaspoon dried thyme for this base batch; scale proportionally.'),I('basil',4,'','small fresh basil sprigs','Use 1 teaspoon dried basil for this base batch; scale proportionally.'),I('marjoram',4,'','small fresh marjoram sprigs','Use 1 teaspoon dried marjoram for this base batch; scale proportionally.'),I('chives',4,'','fresh chive stalks','Use the same number of thin spring-onion greens.'),I('mace',3,'','small blades of mace','Use one-quarter teaspoon ground mace for this base batch; scale proportionally.'),I('bay',3,'','dried bay leaves','Omit if unavailable.'),I('chili',1,'','small dried red chili','Omit for a milder broth.'),I('boilcayenne',.125,'tsp','ground cayenne pepper','Omit for a mild broth.'),I('boilpepper',.5,'tsp','ground black pepper for the broth','Reduce to taste.'),I('boilsalt',75,'g','salt for the crab cooking water','Reduce to taste.'),I('crabmeat',300,'g','cooked picked crabmeat reserved from the boil below; not an additional purchase','Use the same weight of commercially cooked picked crab.'),salt(.125),pepper(.0625),I('lettuce',120,'g','crisp lettuce leaves, washed and dried','Use the same weight of romaine leaves.'),mayo(90),eggs(2),water(750),beet(),water(1000,'beetwater'),celerytips()],
 ['Bring {{crabwater}} to a boil in a large stockpot with {{boilcelery}}, {{allspice}}, {{thyme}}, {{basil}}, {{marjoram}}, {{chives}}, {{mace}}, {{bay}}, {{chili}}, {{boilcayenne}}, {{boilpepper}} and {{boilsalt}}. Simmer for 15 minutes to flavor the water.','Add {{crabs}}, working in batches if necessary so they remain submerged. Return to a boil and cook for about 10–15 minutes for this size, until the meat is opaque and reaches 63°C (145°F). Cooking time varies with crab size; check the meat rather than relying on shell color alone.','Lift out, drain and allow to cool just enough to handle. Remove the upper shells, gills, stomach sacs and internal organs, then crack the claws and body sections and pick out the white meat. Check carefully for shell fragments. Measure {{crabmeat}} into a shallow container and refrigerate promptly until cold. Refrigerate any extra picked meat separately for another dish within 2 days. Discard the shells and strained cooking solids.']+beetsteps()+boil()+[
 'Cut the firm hard-boiled eggs into wedges and keep refrigerated. Season the cold measured crabmeat with {{salt}} and {{pepper}}. Arrange {{lettuce}} on a chilled platter, mound the crabmeat on top and spread {{mayo}} over it. Garnish with the beet slices, egg wedges and {{celerytips}}.',END],
 'The original pint of picked crab is standardized to a modern 300 g working portion, with four servings. The complete referenced boil is expanded using its dozen crabs, celery, allspice, herbs, mace, bay and peppers; water, salt, modern crab size and temperature checking are supplied. Fresh fishmonger-dispatched crabs replace the historical live-boiling instruction. The crab count intentionally supplies more than the measured picked-meat portion because yield varies; surplus meat is accounted for. Beet, egg, lettuce and sauce amounts and full preparation are supplied. Total time assumes vegetables and eggs cook while the crab cools.');finish(r);homemade(r)

r=add(77,'Picayune Salmon with Milk Sauce and Mayonnaise',4,90,'Canned salmon is cooked in a parsley milk sauce, chilled, and served on lettuce beneath mayonnaise with egg and celery garnish.',[
 I('salmon',250,'g','canned cooked salmon, drained weight, skin and large bones removed','Use the same weight of fully cooked boneless salmon.'),I('milk',240,'ml','whole milk','Use the same volume of unsweetened unflavored soy milk.'),I('butter',14,'g','unsalted butter','Use the same weight of a neutral cooking oil.'),I('flour',16,'g','plain wheat flour','Use the same weight of a plain gluten-free flour blend; thickening may differ.'),I('parsley',1,'tbsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.'),salt(.25),pepper(.125),I('lettuce',2,'','small crisp lettuce heads, about 120 g each','Use the same total weight of romaine hearts.'),mayo(90),eggs(2),water(750),celerytips()],
 ['Melt {{butter}} in a saucepan over gentle heat. Stir in {{flour}} and cook for 1 minute without browning. Gradually whisk in {{milk}} until smooth and bring to a gentle simmer.','Flake {{salmon}} and add it to the sauce with {{parsley}}, {{salt}} and {{pepper}}. Simmer gently for about 10 minutes, stirring to prevent sticking, until thoroughly hot and thickened. Transfer to a shallow container, cover and refrigerate promptly until cold, allowing about 45–60 minutes.']+boil()+[
 'Slice the firm hard-boiled eggs and keep chilled. Separate, wash and thoroughly dry {{lettuce}}. Arrange the crisp inner leaves on a platter and tear the outer leaves into fine strips around them.','Spoon the cold salmon mixture onto the lettuce bed and cover with {{mayo}}. Garnish with the egg slices and {{celerytips}} and serve cold.',END],
 'Both imported entries reproduce the same salmon-mayonnaise recipe; entry75 is truncated before the cooling, lettuce assembly and final garnish. The original can size is unspecified and becomes a modern 250 g drained portion. One modern cup milk, one tablespoon butter, two tablespoons flour and one tablespoon parsley are retained with working metric amounts; seasoning, mayonnaise, egg count and four servings are supplied. The full original uses two young lettuce heads and hard-boiled egg and celery garnish.');finish(r);homemade(r)
merge(75,r,'Truncated version of the same Picayune Mayonnaise de Saumon paragraph; complete77 retains cooking, chilling, lettuce assembly, mayonnaise and egg/celery garnish.')

assert len(newids)==6 and len(merges)==2
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full primary-source sauces, complete dish cooking and garnishes, measured homemade variations','repair-batch-034.py'))
for s in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-merge',aliases[s['id']]['reason'],'repair-batch-034.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newAliases=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))
